import {cloud} from './supabase.js?v=3';

const panelId='cloud-sync-panel',activeKey='paper-english-active-user',migrationKey='paper-english-migration';
const blank=()=>({sets:[],attempts:[],settings:{motion:'balanced'},session:null});
const openDb=()=>new Promise((ok,no)=>{let r=indexedDB.open('paper-english',1);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
const read=async key=>{let db=await openDb();return new Promise((ok,no)=>{let r=db.transaction('data').objectStore('data').get(key||'app');r.onsuccess=()=>ok(r.result||null);r.onerror=()=>no(r.error)})};
const write=async(data,key)=>{let db=await openDb();return new Promise((ok,no)=>{let tx=db.transaction('data','readwrite');tx.objectStore('data').put(data,key||'app');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})};
const toast=t=>{let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),4500)};
const escape=x=>String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const session=()=>cloud.session();
const hasWork=d=>!!d&&(d.attempts?.length>0||d.sets?.some(s=>!s.demo)||!!d.session);
const info=d=>(d?.sets?.filter(s=>!s.demo).length||0)+' bộ đề · '+(d?.attempts?.length||0)+' lượt học';
function merge(local,remote){let byId=(a,b)=>{let m=new Map((a||[]).map(x=>[x.id,x]));for(let x of b||[])m.set(x.id,{...m.get(x.id),...x});return [...m.values()]};let sets=new Map((remote?.sets||[]).map(x=>[x.id,x]));for(let x of local?.sets||[]){let old=sets.get(x.id);sets.set(x.id,old?{...old,...x,questions:byId(old.questions,x.questions)}:x)}return {...blank(),...remote,...local,sets:[...sets.values()],attempts:byId(remote?.attempts,local?.attempts),settings:{...(remote?.settings||{}),...(local?.settings||{})},session:local?.session||remote?.session||null}}
async function validSession(){let s=session();if(s?.expires_at&&s.expires_at<Date.now()/1000+60){s=await cloud.refresh(s.refresh_token);cloud.storeSession(s)}return s}
async function sync(show){let s=await validSession();if(!s||!navigator.onLine)return;if(pending()?.userId===s.user.id){if(show)toast('Hãy chọn cách xử lý dữ liệu cục bộ trước khi đồng bộ.');return}let local=await read(),hash=JSON.stringify(local),mark='paper-english-synced-'+s.user.id;if(!show&&hash===localStorage.getItem(mark))return;try{let remote=await cloud.load(s.user.id,s.access_token),data=remote?merge(local,remote):local;await cloud.save(s.user.id,data,s.access_token);await write(data);await write(data,'account:'+s.user.id);localStorage.setItem(mark,JSON.stringify(data));if(show)toast('Đã đồng bộ dữ liệu.')}catch(e){if(show)toast('Chưa đồng bộ được: '+e.message)}}
function pending(){try{return JSON.parse(localStorage.getItem(migrationKey)||'null')}catch{return null}}
function panel(){let s=session(),m=pending();if(!s)return '<section id="'+panelId+'" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">ĐỒNG BỘ SUPABASE</span><h2>Đồng bộ thiết bị</h2></div></div><p>Đăng nhập cùng email trên laptop và iPad để dùng chung dữ liệu.</p><div class="form-grid"><label>Email<input id="cloud-email" type="email" autocomplete="email"></label><label>Mật khẩu<input id="cloud-password" type="password" autocomplete="current-password" minlength="6"></label></div><div class="backup-actions"><button class="button dark" data-cloud="signin">Đăng nhập</button><button class="button" data-cloud="signup">Tạo tài khoản</button><button class="button" data-cloud="reset">Quên mật khẩu</button></div></section>';if(m?.userId===s.user.id)return '<section id="'+panelId+'" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">DỮ LIỆU CỤC BỘ</span><h2>Chuyển dữ liệu an toàn</h2></div></div><p>Phát hiện dữ liệu cũ: <strong>'+escape(info(m.data))+'</strong>. Cloud sẽ không bị ghi đè tự động.</p><div class="backup-actions"><button class="button dark" data-cloud="migrate">Gộp vào tài khoản</button><button class="button" data-cloud="keep-local">Để sau</button></div></section>';return '<section id="'+panelId+'" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">ĐỒNG BỘ SUPABASE</span><h2>Đã đăng nhập</h2></div></div><p>'+escape(s.user.email)+'. '+(navigator.onLine?'Sẵn sàng đồng bộ.':'Đang offline; dữ liệu được giữ cục bộ.')+'</p><div class="backup-actions"><button class="button dark" data-cloud="sync">↻ Đồng bộ ngay</button><button class="button" data-cloud="signout">Đăng xuất</button></div></section>'}
function mount(){let c=document.querySelector('.settings-layout .settings-column');if(c&&!document.getElementById(panelId))c.insertAdjacentHTML('afterbegin',panel())}
new MutationObserver(mount).observe(document.getElementById('app'),{childList:true,subtree:true});document.addEventListener('click',()=>setTimeout(mount));setInterval(mount,500);
async function login(signup){let email=document.getElementById('cloud-email')?.value.trim(),password=document.getElementById('cloud-password')?.value;if(!email||!password)return toast('Hãy nhập email và mật khẩu.');if(password.length<6)return toast('Mật khẩu cần ít nhất 6 ký tự.');try{let r=signup?await cloud.signUp(email,password):await cloud.signIn(email,password),auth=r.session||r;if(!auth.access_token)return toast('Hãy xác nhận email trước, rồi đăng nhập.');let before=await read(),old=localStorage.getItem(activeKey),remote=await cloud.load(auth.user.id,auth.access_token);if(old&&old!==auth.user.id)await write(remote||await read('account:'+auth.user.id)||blank());else if(hasWork(before)){localStorage.setItem(migrationKey,JSON.stringify({userId:auth.user.id,data:before}));await write(remote||blank())}else await write(remote||await read('account:'+auth.user.id)||blank());cloud.storeSession(auth);localStorage.setItem(activeKey,auth.user.id);location.reload()}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-cloud]');if(!b)return;let a=b.dataset.cloud,s=session();if(a==='signin'||a==='signup')return login(a==='signup');if(a==='reset'){let email=document.getElementById('cloud-email')?.value.trim();if(!email)return toast('Nhập email trước.');try{await cloud.resetPassword(email,location.origin);toast('Đã gửi email đặt lại mật khẩu.')}catch(e){toast(e.message)}return}if(a==='sync')return sync(true);if(a==='keep-local'){localStorage.removeItem(migrationKey);location.reload();return}if(a==='migrate'){try{let m=pending(),remote=await cloud.load(s.user.id,s.access_token),data=merge(m.data,remote||blank());await cloud.save(s.user.id,data,s.access_token);await write(data);await write(data,'account:'+s.user.id);localStorage.removeItem(migrationKey);toast('Đã gộp dữ liệu vào cloud.');location.reload()}catch(e){toast(e.message)}return}if(a==='signout'){await sync();await write(await read(),'account:'+s.user.id);await write(blank());await cloud.signOut(s.access_token);localStorage.removeItem(activeKey);location.reload()}});
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action="backup"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();let data=await read(),out={schema_version:2,exported_at:new Date().toISOString(),data:{sets:data.sets||[],attempts:data.attempts||[],settings:data.settings||{},session:data.session||null}};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='paper-english-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã tạo bản sao lưu an toàn.');},true);
document.addEventListener('change',async e=>{if(e.target.id!=='restore')return;e.stopImmediatePropagation();try{let raw=JSON.parse(await e.target.files[0].text()),incoming=raw.schema_version===2?raw.data:raw;if(!Array.isArray(incoming?.sets)||!Array.isArray(incoming?.attempts))throw Error('Định dạng không hợp lệ');let current=await read(),data=merge(current,incoming);if(!confirm('Gộp '+info(incoming)+' vào dữ liệu hiện tại? Dữ liệu hiện tại sẽ được giữ khi trùng.'))return;await write(data);await sync(true);toast('Đã nhập và gộp dữ liệu an toàn.');location.reload()}catch(err){toast('Không thể nhập bản sao lưu: '+err.message)}},true);
window.addEventListener('online',()=>sync(true));setInterval(()=>sync(false),15000);
